func productSessionHTTPTestBinding() ProductSessionHTTPBinding {
	return ProductSessionHTTPBinding{NetworkID: bytes.Repeat([]byte{0xab}, 32), Owner: "0x7e5f4552091a69125d5dfcb7b8c2659029395bdf",
		PKA: bytes.Repeat([]byte{0x31}, PublicKeyASize), PKB: bytes.Repeat([]byte{0x32}, PublicKeyBSize)}
}

func productSessionHTTPTestRaw(t *testing.T, changes map[string]any) []byte {
	t.Helper()
	var u map[string]any
	requireNoError(t, json.Unmarshal([]byte(productSessionHTTPTestUnsigned), &u))
	for k, v := range changes {
		u[k] = v
	}
	var out bytes.Buffer
	e := json.NewEncoder(&out)
	e.SetEscapeHTML(false)
	requireNoError(t, e.Encode(u))
	return bytes.TrimSuffix(out.Bytes(), []byte{'\n'})
}

func TestProductSessionHTTPSDK49FixedE5Vectors(t *testing.T) {
	for i, vector := range []struct {
		network  byte
		unsigned []byte
		hex      string
	}{
		{0xab, []byte(productSessionHTTPTestUnsigned), productSessionHTTPTestSDK0},
		{0xcd, []byte(productSessionHTTPTestUnsigned), productSessionHTTPTestSDK1},
		{0xab, productSessionHTTPTestRaw(t, map[string]any{"path": "/v1/developer/deployments", "nonce": strings.Repeat("b", 43)}), productSessionHTTPTestSDK2},
	} {
		b := productSessionHTTPTestBinding()
		b.NetworkID = bytes.Repeat([]byte{vector.network}, 32)
		want, err := hex.DecodeString(vector.hex)
		requireNoError(t, err)
		message, err := BuildProductSessionHTTPMessage(vector.unsigned, b)
		requireNoError(t, err)
		if !bytes.Equal(message, want) {
			t.Fatalf("SDK49 E5 vector %d changed", i)
		}
		r, err := InspectProductSessionHTTPMessage(want, b, vector.unsigned)
		requireNoError(t, err)
		if !bytes.Equal(r.UnsignedOriginal, vector.unsigned) || !bytes.Equal(r.MessageOriginal, want) {
			t.Fatalf("SDK49 E5 vector %d original changed", i)
		}
	}
}

func TestProductSessionHTTPUnsignedOriginalRejectsAliases(t *testing.T) {
	b := productSessionHTTPTestBinding()
	raw := []byte(productSessionHTTPTestUnsigned)
	comma := bytes.IndexByte(raw, ',')
	reordered := append([]byte{'{'}, raw[comma+1:len(raw)-1]...)
	reordered = append(reordered, ',')
	reordered = append(reordered, raw[1:comma]...)
	reordered = append(reordered, '}')
	for label, bad := range map[string][]byte{
		"duplicate":          []byte(strings.Replace(productSessionHTTPTestUnsigned, `{`, `{"version":"4",`, 1)),
		"escaped duplicate":  []byte(strings.Replace(productSessionHTTPTestUnsigned, `{`, `{"vers\u0069on":"4",`, 1)),
		"unknown":            []byte(strings.Replace(productSessionHTTPTestUnsigned, `{`, `{"unexpected":null,`, 1)),
		"missing nullable":   []byte(strings.Replace(productSessionHTTPTestUnsigned, `"packageId":null,`, "", 1)),
		"missing required":   []byte(strings.Replace(productSessionHTTPTestUnsigned, `,"version":"4"`, "", 1)),
		"case alias":         []byte(strings.Replace(productSessionHTTPTestUnsigned, `"account":`, `"Account":`, 1)),
		"escaped name":       []byte(strings.Replace(productSessionHTTPTestUnsigned, `"account":`, `"acc\u006funt":`, 1)),
		"escaped scalar":     []byte(strings.Replace(productSessionHTTPTestUnsigned, `"GET"`, `"G\u0045T"`, 1)),
		"escaped slash":      []byte(strings.Replace(productSessionHTTPTestUnsigned, `https://`, `https:\/\/`, 1)),
		"reordered":          reordered,
		"leading whitespace": append([]byte{' '}, raw...),
		"trailing LF":        append(clone(raw), '\n'),
		"trailing object":    append(clone(raw), []byte(`{}`)...),
		"invalid UTF8":       append(clone(raw[:len(raw)-1]), 0xff, '}'),
		"top level null":     []byte(`null`),
		"top level array":    []byte(`[]`),
		"oversize":           bytes.Repeat([]byte{'x'}, MaxProductSessionHTTPMessageBytes+1),
	} {
		t.Run(label, func(t *testing.T) {
			_, err := BuildProductSessionHTTPMessage(bad, b)
			requireError(t, err)
		})
	}
}

func TestProductSessionHTTPUnsigned21Values(t *testing.T) {
	b := productSessionHTTPTestBinding()
	for label, change := range map[string]map[string]any{
		"numeric version":        {"version": 4},
		"legacy version":         {"version": "2"},
		"null scalar":            {"nonce": nil},
		"classic key":            {"deviceKey": "classic"},
		"product":                {"productId": "Developer"},
		"client":                 {"clientId": "ab"},
		"application":            {"applicationId": "com_ynx.developer"},
		"bundle mismatch":        {"bundleId": "com.ynx.other"},
		"package mismatch":       {"packageId": "com.ynx.other"},
		"both app ids":           {"packageId": "com.ynx.developer"},
		"opaque id":              {"deviceId": "short"},
		"opaque registration id": {"deviceRegistrationId": "bad/id/0001"},
		"revision zero":          {"deviceRegistrationRevision": "0"},
		"revision alias":         {"deviceRegistrationRevision": "01"},
		"revision overflow":      {"deviceRegistrationRevision": "18446744073709551616"},
		"numeric revision":       {"deviceRegistrationRevision": 9007199254740992},
		"digest uppercase":       {"deviceRegistrationDigest": strings.Repeat("AB", 32)},
		"session digest":         {"sessionBinding": strings.Repeat("a", 63)},
		"body digest":            {"bodyDigest": strings.Repeat("0", 64)},
		"nonce short":            {"nonce": strings.Repeat("a", 31)},
		"nonce long":             {"nonce": strings.Repeat("a", 65)},
		"nonce alias":            {"nonce": strings.Repeat("a", 43) + "="},
		"nonce newline":          {"nonce": strings.Repeat("a", 43) + "\n"},
		"head method":            {"method": "HEAD"},
		"method newline":         {"method": "GET\n"},
		"method case":            {"method": "get"},
		"root path":              {"path": "/"},
		"path query":             {"path": "/projects?all=1"},
		"path percent alias":     {"path": "/projects%2Fother"},
		"path double slash":      {"path": "/projects//other"},
		"path trailing slash":    {"path": "/projects/"},
		"path dot":               {"path": "/projects/./other"},
		"path parent":            {"path": "/projects/../other"},
		"path long":              {"path": "/" + strings.Repeat("a", 256)},
		"time format":            {"issuedAt": "2026-10-26T08:00:00Z"},
		"time calendar":          {"issuedAt": "2026-02-30T08:00:00.000Z"},
		"time leap second":       {"issuedAt": "2026-10-26T08:00:60.000Z"},
		"time offset":            {"issuedAt": "2026-10-26T08:00:00.000+00:00"},
		"empty window":           {"expiresAt": "2026-10-26T08:00:00.000Z"},
		"negative window":        {"expiresAt": "2026-10-26T07:59:59.999Z"},
		"long window":            {"expiresAt": "2026-10-26T08:00:30.001Z"},
		"owner alias":            {"canonicalOwner": "0x7E5f4552091a69125d5dfcb7b8c2659029395bdf"},
		"other owner":            {"canonicalOwner": "0x1111111111111111111111111111111111111111"},
		"account checksum":       {"account": "ynx10e0525sfrf53yh2aljmm3sn9jq5njk7llqhn8q"},
		"account case alias":     {"account": "YNX10E0525SFRF53YH2ALJMM3SN9JQ5NJK7LLQHN80"},
		"account hex alias":      {"account": b.Owner},
	} {
		t.Run(label, func(t *testing.T) {
			_, err := BuildProductSessionHTTPMessage(productSessionHTTPTestRaw(t, change), b)
			requireError(t, err)
		})
	}
	// The message codec preserves all five SDK methods. A product's GET-only
	// consumer and full registration's UUID constraints are separate contracts.
	for _, method := range []string{"DELETE", "GET", "PATCH", "POST", "PUT"} {
		changes := map[string]any{"method": method, "deviceRegistrationId": "opaque:reg-0001", "deviceRegistrationRevision": "18446744073709551615"}
		if method != "GET" {
			changes["bodyDigest"] = strings.Repeat("0", 64)
		}
		_, err := BuildProductSessionHTTPMessage(productSessionHTTPTestRaw(t, changes), b)
		requireNoError(t, err)
	}
	for _, changes := range []map[string]any{
		{"bundleId": nil, "packageId": nil},
		{"bundleId": nil, "packageId": "com.ynx.developer"},
		{"deviceRegistrationRevision": "9007199254740993"},
		{"expiresAt": "2026-10-26T08:00:00.001Z"},
	} {
		_, err := BuildProductSessionHTTPMessage(productSessionHTTPTestRaw(t, changes), b)
		requireNoError(t, err)
	}
}

func TestProductSessionHTTPURLExactSerialization(t *testing.T) {
	for _, c := range []struct {
		value  string
		origin bool
	}{
		{"https://developer.ynxweb4.com", true},
		{"https://developer.ynxweb4.com:444", true},
		{"https://[::ffff:c000:201]", true},
		{"https://127.0.0.1", true},
		{"https://xn--bcher-kva.example", true},
		{"https://0xz", true},
		{"https://developer.ynxweb4.com/", false},
		{"https://developer.ynxweb4.com/a%2Fb", false},
		{"app://ynx-developer", true},
		{"app://Host:123/a", true},
		{"app:///path", false},
		{"app://host/a\\b", false},
		{"app://host%zz/path", false},
		{"ynxdeveloper://wallet-auth/callback", false},
		{"wss://developer.ynxweb4.com/", false},
		{"ftp://example.com/", true},
	} {
		if !productSessionHTTPURL(c.value, c.origin) {
			t.Errorf("SDK URL spelling rejected: %q origin=%v", c.value, c.origin)
		}
	}
	for _, c := range []struct {
		value  string
		origin bool
	}{
		{"https://developer.ynxweb4.com/", true},
		{"https://developer.ynxweb4.com", false},
		{"https://Developer.ynxweb4.com", true},
		{"https://developer.ynxweb4.com:443", true},
		{"https://developer.ynxweb4.com:0444", true},
		{"https://developer.ynxweb4.com:", true},
		{"https://developer.ynxweb4.com:65536", true},
		{"https://developer.ynxweb4.com?x=1", true},
		{"https://developer.ynxweb4.com#fragment", true},
		{"https://user:password@example.com/", false},
		{"https://@example.com/", false},
		{"https://127.1", true},
		{"https://0x7f000001", true},
		{"https://0177.0.0.1", true},
		{"https://[0:0:0:0:0:ffff:c000:201]", true},
		{"https://[::ffff:192.0.2.1]", true},
		{"https://exa%6dple.com", true},
		{"https://xn--", true},
		{"https://bücher.example", true},
		{"HTTPS://example.com", true},
		{"http://example.com/", false},
		{"file://example.com/", false},
		{"javascript://example.com/", false},
		{"data://example.com/", false},
		{"app://", false},
		{"app://host:01/", false},
		{"app://host:/", false},
		{"app://host/a/../b", false},
		{"app://host/a/%2E./b", false},
		{"app://host/a\"b", false},
		{"app://host/é", false},
		{"app://host/\u2028", false},
		{"app://host/\u2029", false},
		{"app://host/\u0085", false},
		{"app://host/\ufeff", false},
		{"app://host/\x00", false},
		{"app://host/\x7f", false},
		{"app://host/" + strings.Repeat("a", 2040), false},
	} {
		if productSessionHTTPURL(c.value, c.origin) {
			t.Errorf("noncanonical SDK URL accepted: %q origin=%v", c.value, c.origin)
		}
	}
}

func TestProductSessionHTTPMessageBindingBoundsAndDetachment(t *testing.T) {
	b := productSessionHTTPTestBinding()
	raw := []byte(productSessionHTTPTestUnsigned)
	message, err := BuildProductSessionHTTPMessage(raw, b)
	requireNoError(t, err)
	for _, part := range []int{0, 1, 2, 3, 4} {
		f, err := DecodeFields(message, 5, MaxProductSessionHTTPMessageBytes)
		requireNoError(t, err)
		f[part][0] ^= 1
		bad, err := EncodeFields(f...)
		requireNoError(t, err)
		_, err = InspectProductSessionHTTPMessage(bad, b, raw)
		requireError(t, err)
	}
	for _, bad := range [][]byte{nil, append(clone(message), 0), bytes.Repeat([]byte{'x'}, MaxProductSessionHTTPMessageBytes+1)} {
		_, err := InspectProductSessionHTTPMessage(bad, b, raw)
		requireError(t, err)
	}
	for _, part := range []string{"network", "owner", "pkA", "pkB"} {
		x := productSessionHTTPTestBinding()
		switch part {
		case "network":
			x.NetworkID = x.NetworkID[:31]
		case "owner":
			x.Owner = strings.ToUpper(x.Owner)
		case "pkA":
			x.PKA = x.PKA[:PublicKeyASize-1]
		case "pkB":
			x.PKB = x.PKB[:PublicKeyBSize-1]
		}
		_, err := BuildProductSessionHTTPMessage(raw, x)
		requireError(t, err)
	}
	r, err := InspectProductSessionHTTPMessage(message, b, raw)
	requireNoError(t, err)
	b.NetworkID[0] ^= 1
	b.PKA[0] ^= 1
	b.PKB[0] ^= 1
	raw[0] = '!'
	message[0] ^= 1
	if r.Binding.NetworkID[0] != 0xab || r.Binding.PKA[0] != 0x31 || r.Binding.PKB[0] != 0x32 || r.UnsignedOriginal[0] != '{' || r.MessageOriginal[0] != 0 {
		t.Fatal("caller input aliases detached public result")
	}
	r.UnsignedOriginal[0] = '!'
	if !bytes.Contains(r.MessageOriginal, []byte(productSessionHTTPTestUnsigned)) {
		t.Fatal("returned unsigned bytes alias returned E5 bytes")
	}
}

func TestProductSessionHTTPMemberRealDualAND(t *testing.T) {
	key, public, err := KeyGen()
	requireNoError(t, err)
	defer key.Destroy()
	b := productSessionHTTPTestBinding()
	b.PKA, b.PKB = clone(public.PKA), clone(public.PKB)
	raw := []byte(productSessionHTTPTestUnsigned)
	message, err := BuildProductSessionHTTPMessage(raw, b)
	requireNoError(t, err)
	batch, err := BatchSign(key, Metadata{ChainID: b.NetworkID, Owner: b.Owner, Purpose: ProductSessionHTTPPurpose}, [][]byte{message}, SignOptions{Optimized: true})
	requireNoError(t, err)
	defer batch.Discard()
	m, err := Extract(batch, 0)
	requireNoError(t, err)
	wire, err := EncodeMember(m)
	requireNoError(t, err)
	r, err := InspectProductSessionHTTPMember(wire, b, raw)
	requireNoError(t, err)
	if !bytes.Equal(r.MessageOriginal, message) || !bytes.Equal(r.Binding.PKA, public.PKA) || !bytes.Equal(r.Binding.PKB, public.PKB) {
		t.Fatal("real AND result changed public DATA")
	}
	for _, branch := range []string{"A", "B"} {
		bad, err := DecodeMember(wire)
		requireNoError(t, err)
		if branch == "A" {
			bad.Certificate.SigmaA[0] ^= 1
		} else {
			bad.Certificate.SigmaB[0] ^= 1
		}
		badWire, err := EncodeMember(bad)
		requireNoError(t, err)
		_, err = InspectProductSessionHTTPMember(badWire, b, raw)
		requireError(t, err) // Structural inspection alone would accept this.
	}
	for _, purpose := range []string{"TX-BATCH", "PRODUCT-SESSION-APPROVAL", "IDE-PROJECT-CONTROL", "ARTIFACT-RELEASE", "AUTH-PROTECTED-KEY-CALL"} {
		bad, err := DecodeMember(wire)
		requireNoError(t, err)
		bad.Certificate.Purpose = purpose
		badWire, err := EncodeMember(bad)
		requireNoError(t, err)
		_, err = InspectProductSessionHTTPMember(badWire, b, raw)
		requireError(t, err)
	}
	for _, part := range []string{"pkA", "pkB", "network", "owner"} {
		x := ProductSessionHTTPBinding{NetworkID: clone(b.NetworkID), Owner: b.Owner, PKA: clone(b.PKA), PKB: clone(b.PKB)}
		switch part {
		case "pkA":
			x.PKA[0] ^= 1
		case "pkB":
			x.PKB[0] ^= 1
		case "network":
			x.NetworkID[0] ^= 1
		case "owner":
			x.Owner = "0x1111111111111111111111111111111111111111"
		}
		_, err := InspectProductSessionHTTPMember(wire, x, raw)
		requireError(t, err)
	}
	changedRaw := productSessionHTTPTestRaw(t, map[string]any{"nonce": strings.Repeat("b", 43)})
	_, err = InspectProductSessionHTTPMember(wire, b, changedRaw)
	requireError(t, err)
	// Give the inspector a valid changed E5 plus matching changed unsigned.
	// Only the actual authenticated trees can reject the retained certificate.
	m.Message, err = BuildProductSessionHTTPMessage(changedRaw, b)
	requireNoError(t, err)
	changedWire, err := EncodeMember(m)
	requireNoError(t, err)
	_, err = InspectProductSessionHTTPMember(changedWire, b, changedRaw)
	requireError(t, err)
	for _, bad := range [][]byte{nil, append(clone(wire), 0), bytes.Repeat([]byte{'x'}, MaxProductSessionHTTPMemberBytes+1)} {
		_, err := InspectProductSessionHTTPMember(bad, b, raw)
		requireError(t, err)
	}
	outer, err := DecodeFields(wire, 4, MaxMemberBytes)
	requireNoError(t, err)
	proof, err := DecodeFields(outer[3], 3, MaxProofBytes)
	requireNoError(t, err)
	proof[0] = U32(1)
	outer[3], err = EncodeFields(proof...)
	requireNoError(t, err)
	badIndex, err := EncodeFields(outer...)
	requireNoError(t, err)
	_, err = InspectProductSessionHTTPMember(badIndex, b, raw)
	requireError(t, err)
	m, err = DecodeMember(wire)
	requireNoError(t, err)
	m.Certificate.N = 2
	m.PathA, m.PathB = [][]byte{make([]byte, 64)}, [][]byte{make([]byte, 64)}
	badN, err := EncodeMember(m)
	requireNoError(t, err)
	_, err = InspectProductSessionHTTPMember(badN, b, raw)
	requireError(t, err)
}
